        introText: "Speed measures how quickly an object moves across a distance. Velocity includes both speed and direction, while acceleration describes how speed or direction changes over time.",
        exampleText: "Motion facts:\n\n🚗 Speed = Distance ÷ Time\n↗️ Velocity = speed + direction (e.g. 60 km/h north)\n🏎️ Acceleration = change in speed over time\n\nA distance-time graph shows steeper lines for faster speeds.",
        iconSystemName: "speedometer",
        gradeLabel: "Grade 6"
    ),

    SciTopicDefinition(
        id: 43,
        nodeTitle: "Weather Patterns",
        introTitle: "Weather Patterns & Prediction Quest",
        introText: "Meteorologists study weather patterns to make forecasts. Air pressure, temperature, and humidity interact to form fronts and storms. Reading weather maps helps predict what weather is coming.",
        exampleText: "Weather clues:\n\n🔵 Cold front  -  brings colder temperatures and storms\n🔴 Warm front  -  brings warmer, cloudy weather\n⬇️ Low pressure  -  stormy, cloudy skies\n⬆️ High pressure  -  calm, sunny skies\n🌪️ Severe storms form when warm and cold air collide",
        iconSystemName: "cloud.bolt.rain.fill",
        gradeLabel: "Grade 5"
    ),

    SciTopicDefinition(
        id: 44,
        nodeTitle: "Tech & Tools",
        introTitle: "Technology & Tools Quest",
        introText: "Technology is any tool or system that people create to solve problems or extend human capabilities. From the wheel to the smartphone, inventions have shaped how we live, work, and communicate throughout history.",
        exampleText: "Tool timeline:\n\n🪨 Stone tools  -  2.5 million years ago\n⚙️ Wheel  -  ~3500 BCE\n🖨️ Printing press  -  1440s\n💡 Electric light bulb  -  1879\n📱 Smartphone  -  2007\n\nEach invention built on earlier technologies.",
        iconSystemName: "hammer.fill",
        gradeLabel: "Grade 3"
    ),

    SciTopicDefinition(
        id: 45,
        nodeTitle: "Excretory System",
        introTitle: "Excretory & Urinary System Quest",
        introText: "The excretory system removes waste products from the body to keep it healthy. The kidneys filter blood to produce urine, which carries dissolved waste out of the body. Staying hydrated keeps this system working well.",
        exampleText: "Waste removal:\n\n🫘 Kidneys  -  filter blood ~200 times a day\n💧 Urine  -  water + dissolved salts + urea\n🫁 Lungs  -  remove CO₂ as you breathe out\n💦 Skin  -  removes waste through sweat\n\nDrink 6–8 glasses of water daily to help your kidneys!",
        iconSystemName: "drop.triangle.fill",
        gradeLabel: "Grade 6"
    ),

    SciTopicDefinition(
        id: 46,
        nodeTitle: "Nutrition & Diet",
        introTitle: "Nutrition & Healthy Eating Quest",
        introText: "Food gives our bodies energy and the nutrients needed to grow, repair, and stay healthy. A balanced diet includes a variety of food groups, each supplying vitamins, minerals, proteins, fats, and carbohydrates.",
        exampleText: "Food groups:\n\n🌾 Grains  -  energy (carbohydrates)\n🥦 Vegetables  -  vitamins & minerals\n🍎 Fruits  -  vitamins, fibre, natural sugars\n🥛 Dairy  -  calcium for bones\n🥩 Protein foods  -  muscle building\n\nTip: half your plate should be fruits and vegetables!",
        iconSystemName: "fork.knife",
        gradeLabel: "Grade 4"
    ),

    SciTopicDefinition(
        id: 47,
        nodeTitle: "Electricity & Circuits",
        introTitle: "Electricity & Circuits Quest",
        introText: "Electricity is a form of energy caused by the flow of tiny particles called electrons. A circuit is a complete path that electricity travels along. Without a complete circuit, electricity cannot flow and devices will not work.",
        exampleText: "Circuit basics:\n\n🔋 Battery  -  provides the energy (voltage)\n💡 Bulb  -  converts electrical energy to light\n🔌 Wire  -  carries the current\n🔴 Switch  -  opens or closes the circuit\n\nSeries circuit: all components in one loop\nParallel circuit: components on separate branches",
        iconSystemName: "bolt.fill",
        gradeLabel: "Grade 4"
    ),

    SciTopicDefinition(
        id: 48,
        nodeTitle: "Magnetism",
        introTitle: "Magnetism Quest",
        introText: "Magnets have two poles: north and south. Opposite poles attract each other; like poles repel. The area around a magnet where its force acts is called a magnetic field. Earth itself acts like a giant magnet, which is why compasses work.",
        exampleText: "Magnet facts:\n\n🧲 North & South poles  -  opposite poles attract\n❌ Like poles repel  -  N–N and S–S push apart\n🗺️ Compass needle  -  points to Earth's magnetic north\n📎 Magnetic materials: iron, nickel, cobalt\n🚫 Non-magnetic: plastic, wood, aluminium",
        iconSystemName: "magnet.fill",
        gradeLabel: "Grade 4"
    ),

    SciTopicDefinition(
        id: 49,
        nodeTitle: "The Human Body",
        introTitle: "The Human Body Quest",
        introText: "Your body is made up of many systems that work together to keep you alive. Key systems include the skeletal system (bones), muscular system (muscles), digestive system (breaking down food), and circulatory system (blood and heart).",
        exampleText: "Body systems:\n\n🦴 Skeletal  -  206 bones, gives shape and support\n💪 Muscular  -  muscles move bones and organs\n❤️ Circulatory  -  heart pumps blood around the body\n🍎 Digestive  -  mouth to stomach to intestines\n🫁 Respiratory  -  lungs take in oxygen, release CO₂",
        iconSystemName: "figure.stand",
        gradeLabel: "Grade 4"
    ),

    SciTopicDefinition(
        id: 50,
        nodeTitle: "Rocks & Minerals",
        introTitle: "Rocks & Minerals Quest",
        introText: "Rocks are made of one or more minerals. There are three main types of rock: igneous (formed from cooled magma), sedimentary (formed from layers of sediment pressed together), and metamorphic (changed by heat and pressure inside Earth).",
        exampleText: "Rock types:\n\n🌋 Igneous  -  granite, basalt (from cooled magma)\n🏔️ Sedimentary  -  sandstone, limestone (from layers)\n💎 Metamorphic  -  marble, slate (heat & pressure)\n\nMineral properties: hardness, colour, luster\nThe Mohs scale ranks hardness from 1 (talc) to 10 (diamond)",
        iconSystemName: "mountain.2.fill",
        gradeLabel: "Grade 4"
    ),

    SciTopicDefinition(
        id: 51,
        nodeTitle: "Space & Solar System",
        introTitle: "Space & Solar System Quest",
        introText: "Our solar system has eight planets that orbit the Sun. The inner four planets are small and rocky; the outer four are large gas or ice giants. Earth is the third planet and the only one known to support life.",
        exampleText: "8 Planets in order from the Sun:\n\n☿ Mercury · ♀ Venus · 🌍 Earth · ♂ Mars\n♃ Jupiter · ♄ Saturn · ⛢ Uranus · ♆ Neptune\n\n🌕 Moon orbits Earth\n⭐ Sun  -  a star at the centre\n🪐 Saturn has the most visible rings",
        iconSystemName: "sparkles",
        gradeLabel: "Grade 4"
    ),

    SciTopicDefinition(
        id: 52,
        nodeTitle: "Chemical Changes",
        introTitle: "Chemical Changes Quest",
        introText: "A chemical change produces one or more new substances that are different from the original materials. Signs include colour change, gas bubbles, heat or light being released, and a new smell forming. Chemical changes are usually irreversible.",
        exampleText: "Chemical change clues:\n\n🔥 Burning wood  -  ash and CO₂ form (new substances)\n🟠 Iron rusting  -  iron + oxygen → iron oxide\n🧁 Baking a cake  -  raw batter becomes solid sponge\n🫧 Vinegar + baking soda  -  fizzing gas produced\n\nCompare with physical change: melting ice (still water)",
        iconSystemName: "flask.fill",
        gradeLabel: "Grade 5"
    ),

    SciTopicDefinition(
        id: 53,
        nodeTitle: "Ecosystems",
        introTitle: "Ecosystems Quest",
        introText: "An ecosystem is all the living things in an area together with the non-living parts of their environment. Producers make food using sunlight, consumers eat other organisms, and decomposers break down dead material, recycling nutrients back into the ecosystem.",
        exampleText: "Ecosystem roles:\n\n🌿 Producers  -  plants, algae (make food)\n🐇 Primary consumers  -  herbivores eat plants\n🦊 Secondary consumers  -  carnivores eat herbivores\n🍄 Decomposers  -  fungi, bacteria break down dead things\n\nIf one species disappears, it can affect the whole system.",
        iconSystemName: "globe.americas.fill",
        gradeLabel: "Grade 5"
    ),

    SciTopicDefinition(
        id: 54,
        nodeTitle: "Genetics & Inheritance",
        introTitle: "Genetics & Inheritance Quest",
        introText: "Traits are characteristics passed from parents to offspring through genes. Genes are found on chromosomes inside the nucleus of every cell. Some traits are dominant (need only one copy to show) and some are recessive (need two copies to show).",
        exampleText: "Inheritance basics:\n\n🧬 DNA  -  carries all genetic information\n📍 Gene  -  section of DNA that codes for a trait\n🟠 Dominant trait  -  shown with a capital letter (e.g. B)\n⚪ Recessive trait  -  shown with lowercase (e.g. b)\n\nExample: Brown eyes (B) is dominant over blue eyes (b).\nA child with Bb will have brown eyes.",
        iconSystemName: "dna",
        gradeLabel: "Grade 5"
    ),

    SciTopicDefinition(
        id: 55,
        nodeTitle: "Technology & Engineering",
        introTitle: "Technology & Engineering Quest",
        introText: "Technology is any tool or system humans create to solve problems. Engineers design solutions by following a process: define the problem, brainstorm ideas, build a prototype, test it, and improve it. This cycle can repeat many times.",
        exampleText: "Engineering design steps:\n\n❓ Define  -  what problem needs solving?\n💡 Brainstorm  -  think of many solutions\n🔨 Build  -  make a prototype (first model)\n🧪 Test  -  does it solve the problem?\n🔁 Improve  -  make it better and test again!\n\nExamples of technology: bridges, medicines, apps, vehicles",
        iconSystemName: "wrench.and.screwdriver.fill",
        gradeLabel: "Grade 4"
    ),
    ]

